#include <iostream>
#include <set>
#include <algorithm>

template <typename T>
class SetUnion {
public:
    static std::set<T> compute(const std::set<T>& a, const std::set<T>& b) {
        std::set<T> result;
        std::set_union(a.begin(), a.end(), b.begin(), b.end(), std::inserter(result, result.end()));
        return result;
    }
};

// Specialization for int type
template <>
class SetUnion<int> {
public:
    static std::set<int> compute(const std::set<int>& a, const std::set<int>& b) {
        // Custom implementation for int sets
        std::set<int> result;
        // For demonstration, same as general but could be optimized
        std::set_union(a.begin(), a.end(), b.begin(), b.end(), std::inserter(result, result.end()));
        return result;
    }
};

int main() {
    std::set<int> set1 = {1, 3, 5};
    std::set<int> set2 = {2, 3, 4};
    auto union_set = SetUnion<int>::compute(set1, set2);
    for (int n : union_set) {
        std::cout << n << ' ';
    }
    return 0;
}
